insert into public.lessons (id, level, position, published, data) values
  ('keywords', 0, 12, true, '{"minutes":7,"icon":"chart","title":{"uz":"Kalit so''zlar: xaridor qanday qidiradi","ru":"Ключевые слова: как ищет покупатель"},"summary":{"uz":"Asosiy va uzun kalit so''zlarni topish va joylashtirish.","ru":"Как найти и разместить основные и длинные запросы."},"slides":[{"kind":"learn","title":{"uz":"Nega kalit so''z muhim","ru":"Почему важны ключевые слова"},"body":{"uz":"Amazon''da ko''p xaridor mahsulotni qidiruv orqali topadi. Agar listingingizda xaridor yozadigan so''zlar bo''lmasa, mahsulotingiz qidiruvda chiqmaydi va hech kim uni ko''rmaydi.","ru":"Большинство покупателей на Amazon находят товар через поиск. Если в карточке нет слов, которые пишет покупатель, товар не появится в поиске и его никто не увидит."},"visual":{"kind":"flow","steps":[{"uz":"Xaridor yozadi","ru":"Покупатель вводит"},{"uz":"Amazon qidiradi","ru":"Amazon ищет"},{"uz":"Mos listing","ru":"Подходящая карточка"},{"uz":"Xarid","ru":"Покупка"}]}},{"kind":"learn","title":{"uz":"Asosiy va uzun so''zlar","ru":"Основные и длинные запросы"},"body":{"uz":"Asosiy so''z qisqa va ommabop, lekin raqobat kuchli. Uzun so''z aniqroq: uni kamroq odam qidiradi, lekin ular sotib olishga tayyorroq.","ru":"Основной запрос короткий и популярный, но конкуренция высокая. Длинный запрос точнее: его ищут реже, зато такие покупатели чаще покупают."},"visual":{"kind":"compare","left":{"title":{"uz":"Asosiy","ru":"Основной"},"items":[{"uz":"\"silicone spoon\"","ru":"«silicone spoon»"},{"uz":"Ko''p qidiruv","ru":"Много поисков"},{"uz":"Kuchli raqobat","ru":"Сильная конкуренция"}]},"right":{"title":{"uz":"Uzun","ru":"Длинный"},"items":[{"uz":"\"heat resistant silicone cooking spoon\"","ru":"«heat resistant silicone cooking spoon»"},{"uz":"Kamroq qidiruv","ru":"Меньше поисков"},{"uz":"Aniq niyat","ru":"Чёткое намерение"}]}}},{"kind":"learn","title":{"uz":"So''zlarni qayerdan topish","ru":"Где искать слова"},"body":{"uz":"Bepul usullardan boshlang. Har bir topilgan so''zni ro''yxatga yozing va qayerdan olganingizni belgilang.","ru":"Начните с бесплатных способов. Каждое найденное слово записывайте в список и отмечайте, откуда оно."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Amazon qidiruv qatoridagi avtomatik takliflar","ru":"Подсказки в строке поиска Amazon"},{"uz":"Eng yaxshi raqobatchilarning nomlari","ru":"Названия лучших конкурентов"},{"uz":"Xaridor sharhlaridagi so''zlar","ru":"Слова из отзывов покупателей"},{"uz":"\"Customers also search\" bloklari","ru":"Блоки «Покупатели также ищут»"}]}},{"kind":"learn","title":{"uz":"So''zlarni qayerga qo''yish","ru":"Куда ставить слова"},"body":{"uz":"Eng muhim so''z nomning boshida bo''lsin. Qolganlari punktlar va tavsifga tabiiy holda kirsin. Ko''rinmaydigan \"search terms\" maydoniga sinonimlarni yozing. So''zlarni ketma-ket takrorlab to''ldirmang: bu o''qishni buzadi.","ru":"Главное слово – в начале названия. Остальные естественно входят в пункты и описание. Синонимы пишите в скрытое поле «search terms». Не забивайте текст повторами: это портит чтение."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Nom: asosiy so''z birinchi","ru":"Название: главное слово первым"},{"uz":"5 ta punkt: foyda + so''zlar","ru":"5 пунктов: польза + слова"},{"uz":"Search terms: sinonimlar","ru":"Search terms: синонимы"}]}},{"kind":"quiz","question":{"uz":"Qaysi so''zni qidirgan xaridor sotib olishga tayyorroq?","ru":"Кто из покупателей скорее купит?"},"options":[{"uz":"\"spoon\"","ru":"«spoon»"},{"uz":"\"heat resistant silicone cooking spoon\"","ru":"«heat resistant silicone cooking spoon»"},{"uz":"\"kitchen\"","ru":"«kitchen»"}],"correct":1,"explain":{"uz":"Uzun va aniq so''z xaridor nimani xohlashini biladi degani.","ru":"Длинный и точный запрос значит, что покупатель знает, что хочет."}}]}'::jsonb),
  ('competitors', 0, 13, true, '{"minutes":7,"icon":"globe","title":{"uz":"Raqobatchilarni o''rganish","ru":"Анализ конкурентов"},"summary":{"uz":"Top-10 listing va 1–3 yulduzli sharhlardan foydalanish.","ru":"Как читать топ-10 и отзывы на 1–3 звезды."},"slides":[{"kind":"learn","title":{"uz":"Birinchi sahifani tahlil qiling","ru":"Разберите первую страницу"},"body":{"uz":"Asosiy kalit so''z bo''yicha birinchi 10 ta mahsulotni jadvalga yozing. Bu sizning haqiqiy raqobatchilaringiz.","ru":"Выпишите в таблицу первые 10 товаров по основному запросу. Это ваши реальные конкуренты."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Narxi","ru":"Цена"},{"uz":"Sharhlar soni va reytingi","ru":"Число отзывов и рейтинг"},{"uz":"BSR","ru":"BSR"},{"uz":"Rasm va nom sifati","ru":"Качество фото и названия"},{"uz":"Kim sotadi: brend yoki kichik sotuvchi","ru":"Кто продаёт: бренд или небольшой продавец"}]}},{"kind":"learn","title":{"uz":"Eng qimmatli joy: yomon sharhlar","ru":"Самое ценное: плохие отзывы"},"body":{"uz":"1–3 yulduzli sharhlarni o''qing. Xaridorlar nimadan norozi? Bir xil shikoyat ko''p takrorlansa, bu sizning imkoniyatingiz: shu muammoni hal qilgan mahsulot yaxshiroq sotiladi.","ru":"Читайте отзывы на 1–3 звезды. Чем недовольны покупатели? Если жалоба повторяется, это ваш шанс: товар без этой проблемы будет продаваться лучше."},"visual":{"kind":"flow","steps":[{"uz":"Shikoyatni toping","ru":"Найти жалобу"},{"uz":"Sababini tushuning","ru":"Понять причину"},{"uz":"Yechim qiling","ru":"Сделать решение"}]}},{"kind":"learn","title":{"uz":"Misol","ru":"Пример"},"body":{"uz":"Silikon qoshiq sharhlarida \"dastasi qiziydi\" va \"tez yorilib ketadi\" degan shikoyatlar ko''p. Demak, issiqqa chidamli dasta va qalinroq silikon – yaxshi farq.","ru":"В отзывах на силиконовую ложку часто пишут «ручка нагревается» и «быстро трескается». Значит, термостойкая ручка и более толстый силикон – хорошее отличие."},"visual":{"kind":"compare","left":{"title":{"uz":"Shikoyat","ru":"Жалоба"},"items":[{"uz":"Dasta qiziydi","ru":"Ручка нагревается"},{"uz":"Tez yoriladi","ru":"Быстро трескается"}]},"right":{"title":{"uz":"Sizning yechimingiz","ru":"Ваше решение"},"items":[{"uz":"Issiqqa chidamli dasta","ru":"Термостойкая ручка"},{"uz":"Qalinroq material","ru":"Более толстый материал"}]}}},{"kind":"learn","title":{"uz":"Qachon kirmaslik kerak","ru":"Когда не стоит заходить"},"body":{"uz":"Agar birinchi sahifadagi deyarli hamma mahsulotda minglab sharh bo''lsa va narxlar juda past bo''lsa, yangi sotuvchiga joy kam. Boshqa mahsulot yoki aniqroq bo''lim qidiring.","ru":"Если почти у всех на первой странице тысячи отзывов и очень низкие цены, новичку там мало места. Ищите другой товар или более узкую нишу."}},{"kind":"quiz","question":{"uz":"Mahsulotni yaxshilash uchun eng foydali manba qaysi?","ru":"Что полезнее всего для улучшения товара?"},"options":[{"uz":"5 yulduzli sharhlar","ru":"Отзывы на 5 звёзд"},{"uz":"1–3 yulduzli sharhlar","ru":"Отзывы на 1–3 звезды"},{"uz":"Mahsulot rangi","ru":"Цвет товара"}],"correct":1,"explain":{"uz":"Past baholi sharhlar xaridor nimadan norozi ekanini aniq ko''rsatadi.","ru":"Низкие оценки прямо показывают, чем недовольны покупатели."}}]}'::jsonb),
  ('differentiation', 0, 14, true, '{"minutes":5,"icon":"sparkle","title":{"uz":"Mahsulotni boshqalardan ajratish","ru":"Как выделить товар"},"summary":{"uz":"Nusxa emas, yaxshilangan mahsulot.","ru":"Не копия, а улучшенный товар."},"slides":[{"kind":"learn","title":{"uz":"Nusxa ko''chirish nega ishlamaydi","ru":"Почему копия не работает"},"body":{"uz":"Agar mahsulotingiz boshqalarnikiga aynan o''xshasa, xaridor faqat narxga qaraydi. Natijada narx tushadi va foyda yo''qoladi.","ru":"Если ваш товар такой же, как у всех, покупатель смотрит только на цену. Цена падает, и прибыль исчезает."}},{"kind":"learn","title":{"uz":"Farq qilish usullari","ru":"Способы отличиться"},"body":{"uz":"Kichik, lekin xaridor sezadigan yaxshilanish yetarli. U narxni oshirmasligi yoki ozgina oshirishi kerak.","ru":"Достаточно небольшого улучшения, которое заметит покупатель. Оно не должно сильно поднимать себестоимость."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Shikoyatni tuzatish","ru":"Исправить частую жалобу"},{"uz":"Foydali to''plam (2 ta o''rniga 3 ta)","ru":"Полезный набор (3 вместо 2)"},{"uz":"Yaxshiroq material","ru":"Материал получше"},{"uz":"Chiroyli qadoq va yo''riqnoma","ru":"Хорошая упаковка и инструкция"}]}},{"kind":"learn","title":{"uz":"Xarajatni tekshiring","ru":"Проверьте себестоимость"},"body":{"uz":"Har bir yaxshilanishdan keyin foydani qayta hisoblang. Agar yaxshilanish foydani yeb qo''ysa, u to''g''ri emas.","ru":"После каждого улучшения пересчитайте прибыль. Если улучшение съедает прибыль, оно не подходит."},"visual":{"kind":"big","icon":"calc","text":{"uz":"Mahsulotlar bo''limidagi kalkulyatorda tekshiring","ru":"Проверьте в калькуляторе раздела «Товары»"}}},{"kind":"quiz","question":{"uz":"Qaysi yaxshilanish eng to''g''ri?","ru":"Какое улучшение лучше всего?"},"options":[{"uz":"Mashhur brend logotipini qo''shish","ru":"Добавить логотип известного бренда"},{"uz":"Ko''p uchraydigan shikoyatni tuzatish","ru":"Исправить частую жалобу"},{"uz":"Narxni ikki baravar oshirish","ru":"Поднять цену вдвое"}],"correct":1,"explain":{"uz":"Shikoyatni tuzatish xaridorga haqiqiy foyda beradi va qonuniy.","ru":"Исправление жалобы реально полезно покупателю и законно."}}]}'::jsonb),
  ('brand', 0, 15, true, '{"minutes":6,"icon":"shield","title":{"uz":"Brend va tovar belgisi","ru":"Бренд и товарный знак"},"summary":{"uz":"Private label, trademark va Brand Registry.","ru":"Private label, товарный знак и Brand Registry."},"slides":[{"kind":"learn","title":{"uz":"Private label nima","ru":"Что такое private label"},"body":{"uz":"Private label – zavod ishlab chiqargan mahsulotni o''z brendingiz bilan sotish. Shunda listing sizniki bo''ladi va boshqalar unga osonlikcha yopisha olmaydi.","ru":"Private label – продажа товара фабрики под вашим брендом. Тогда карточка ваша, и к ней сложнее «прицепиться» другим продавцам."},"visual":{"kind":"flow","steps":[{"uz":"Zavod mahsuloti","ru":"Товар фабрики"},{"uz":"Sizning brendingiz","ru":"Ваш бренд"},{"uz":"Sizning listingingiz","ru":"Ваша карточка"}]}},{"kind":"learn","title":{"uz":"Tovar belgisi (trademark)","ru":"Товарный знак"},"body":{"uz":"Brend nomini himoya qilish uchun tovar belgisi ro''yxatdan o''tkaziladi. AQSh uchun bu USPTO orqali qilinadi. Narx va muddatlarni rasmiy sahifadan tekshiring, ko''pincha yurist yordami kerak bo''ladi.","ru":"Чтобы защитить название бренда, регистрируют товарный знак. Для США это делается через USPTO. Цены и сроки проверяйте на официальном сайте, часто нужна помощь юриста."}},{"kind":"learn","title":{"uz":"Amazon Brand Registry","ru":"Amazon Brand Registry"},"body":{"uz":"Brand Registry brend egasiga listingni boshqarish, soxta sotuvchilardan himoya va qo''shimcha imkoniyatlar beradi. Unga kirish uchun odatda ro''yxatdan o''tgan yoki ariza berilgan tovar belgisi kerak.","ru":"Brand Registry даёт владельцу бренда контроль над карточкой, защиту от подделок и дополнительные функции. Для входа обычно нужен зарегистрированный или поданный товарный знак."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Listing ustidan nazorat","ru":"Контроль над карточкой"},{"uz":"Soxta sotuvchilardan himoya","ru":"Защита от подделок"},{"uz":"Kengaytirilgan rasm va matn (A+)","ru":"Расширенный контент (A+)"}]}},{"kind":"learn","title":{"uz":"Nom tanlashda","ru":"При выборе названия"},"body":{"uz":"Nom qisqa, eslab qolinadigan va boshqa birovning brendiga o''xshamaydigan bo''lsin. Avval USPTO bazasida shunga o''xshash nom bor-yo''qligini tekshiring.","ru":"Название должно быть коротким, запоминающимся и не похожим на чужой бренд. Сначала проверьте похожие названия в базе USPTO."}},{"kind":"quiz","question":{"uz":"Brand Registry uchun odatda nima kerak?","ru":"Что обычно нужно для Brand Registry?"},"options":[{"uz":"Ko''p sharhlar","ru":"Много отзывов"},{"uz":"Tovar belgisi (ro''yxatdan o''tgan yoki ariza berilgan)","ru":"Товарный знак (зарегистрированный или поданный)"},{"uz":"Katta reklama byudjeti","ru":"Большой рекламный бюджет"}],"correct":1,"explain":{"uz":"Brand Registry brend egaligini tovar belgisi orqali tasdiqlaydi.","ru":"Brand Registry подтверждает владение брендом через товарный знак."}}]}'::jsonb),
  ('barcodes', 0, 16, true, '{"minutes":5,"icon":"clipboard","title":{"uz":"Shtrix-kodlar: UPC va FNSKU","ru":"Штрихкоды: UPC и FNSKU"},"summary":{"uz":"Qaysi kod nima uchun va qayerdan olinadi.","ru":"Какой код зачем нужен и где его взять."},"slides":[{"kind":"learn","title":{"uz":"Ikki xil kod","ru":"Два разных кода"},"body":{"uz":"UPC (GTIN) – mahsulotning dunyo bo''yicha raqami, listing yaratishda kerak. FNSKU – Amazon beradigan ichki kod, u omborda aynan sizning tovaringizni ajratib turadi.","ru":"UPC (GTIN) – международный номер товара, нужен для создания карточки. FNSKU – внутренний код Amazon, по нему на складе отличают именно ваш товар."},"visual":{"kind":"compare","left":{"title":{"uz":"UPC / GTIN","ru":"UPC / GTIN"},"items":[{"uz":"Listing yaratish uchun","ru":"Для создания карточки"},{"uz":"GS1 dan olinadi","ru":"Берётся в GS1"}]},"right":{"title":{"uz":"FNSKU","ru":"FNSKU"},"items":[{"uz":"FBA ombori uchun","ru":"Для склада FBA"},{"uz":"Amazon beradi","ru":"Выдаёт Amazon"}]}}},{"kind":"learn","title":{"uz":"UPC ni qayerdan olish","ru":"Где взять UPC"},"body":{"uz":"Amazon odatda GS1 tashkilotidan olingan kodlarni talab qiladi. Arzon \"qayta sotilgan\" kodlar rad etilishi mumkin. Ba''zi hollarda brend egalari GTIN dan ozod qilinishi mumkin – shartlarini Seller Central''da tekshiring.","ru":"Amazon обычно требует коды, полученные в GS1. Дешёвые перепроданные коды могут отклонить. Владельцы бренда иногда могут получить исключение из GTIN – условия смотрите в Seller Central."}},{"kind":"learn","title":{"uz":"FNSKU yorlig''i","ru":"Этикетка FNSKU"},"body":{"uz":"FBA''ga yuboriladigan har bir dona ustida FNSKU yorlig''i bo''lishi kerak. Uni zavodga yuborib, qadoqlashda yopishtirtirish mumkin. Yorliq o''qiladigan va boshqa shtrix-kodni yopib turadigan bo''lsin.","ru":"На каждой единице для FBA должна быть этикетка FNSKU. Её можно отправить на фабрику, чтобы наклеили при упаковке. Этикетка должна читаться и закрывать другие штрихкоды."},"visual":{"kind":"flow","steps":[{"uz":"Seller Central","ru":"Seller Central"},{"uz":"FNSKU yorlig''i","ru":"Этикетка FNSKU"},{"uz":"Zavod yopishtiradi","ru":"Фабрика клеит"},{"uz":"Ombor skanerlaydi","ru":"Склад сканирует"}]}},{"kind":"quiz","question":{"uz":"FBA omborida tovaringizni qaysi kod orqali taniydi?","ru":"По какому коду склад FBA узнаёт ваш товар?"},"options":[{"uz":"FNSKU","ru":"FNSKU"},{"uz":"Pasport raqami","ru":"Номер паспорта"},{"uz":"Narx","ru":"Цена"}],"correct":0,"explain":{"uz":"FNSKU – Amazon ombori uchun sizning tovaringizning ichki kodi.","ru":"FNSKU – внутренний код вашего товара для склада Amazon."}}]}'::jsonb),
  ('fba-prep', 0, 17, true, '{"minutes":6,"icon":"box","title":{"uz":"FBA uchun qadoqlash va jo''natish","ru":"Упаковка и отправка в FBA"},"summary":{"uz":"Dona, quti va yorliqlar qoidalari.","ru":"Правила для единиц, коробок и этикеток."},"slides":[{"kind":"learn","title":{"uz":"Nega qoidalar muhim","ru":"Почему правила важны"},"body":{"uz":"Amazon ombori qoidaga mos kelmagan tovarni qabul qilmasligi, qayta qadoqlash uchun pul olishi yoki qaytarib yuborishi mumkin. Aniq talablar Seller Central''dagi \"FBA prep\" bo''limida.","ru":"Склад Amazon может не принять товар, взять плату за переупаковку или вернуть его. Точные требования – в разделе «FBA prep» в Seller Central."}},{"kind":"learn","title":{"uz":"Har bir dona uchun","ru":"Для каждой единицы"},"body":{"uz":"Asosiy talablar odatda shular. Mahsulotingiz toifasiga qo''shimcha talablar bo''lishi mumkin.","ru":"Основные требования обычно такие. Для вашей категории могут быть дополнительные."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"FNSKU yorlig''i aniq ko''rinadi","ru":"Этикетка FNSKU хорошо видна"},{"uz":"Ochilishi katta polietilen paketda bo''g''ilish haqida ogohlantirish","ru":"На пакете с большим отверстием – предупреждение об удушении"},{"uz":"To''plam bo''lsa: \"To''plam, alohida sotilmaydi\" yorlig''i","ru":"Для набора: этикетка «Набор, не продаётся отдельно»"},{"uz":"Sinadigan qism himoyalangan","ru":"Хрупкое защищено"}]}},{"kind":"learn","title":{"uz":"Qutilar uchun","ru":"Для коробок"},"body":{"uz":"Qutilar uchun o''lcham va og''irlik chegaralari bor; og''ir qutilarga maxsus belgi kerak. Har bir qutiga Amazon beradigan quti yorlig''i yopishtiriladi. Chegaralarni joriy qoidalardan tekshiring.","ru":"Для коробок есть лимиты размера и веса; тяжёлым нужна специальная отметка. На каждую коробку клеится этикетка, которую выдаёт Amazon. Лимиты проверяйте в актуальных правилах."},"visual":{"kind":"flow","steps":[{"uz":"Jo''natma yaratish","ru":"Создать поставку"},{"uz":"Quti yorliqlari","ru":"Этикетки коробок"},{"uz":"Ekspeditorga topshirish","ru":"Передать экспедитору"},{"uz":"Omborga qabul","ru":"Приёмка на складе"}]}},{"kind":"quiz","question":{"uz":"Qoidaga mos qadoqlanmagan tovar bilan nima bo''lishi mumkin?","ru":"Что может случиться с неправильно упакованным товаром?"},"options":[{"uz":"Hech narsa","ru":"Ничего"},{"uz":"Rad etilishi yoki qayta qadoqlash uchun pul olinishi","ru":"Отказ в приёмке или плата за переупаковку"},{"uz":"Avtomatik ko''proq sotiladi","ru":"Будет продаваться лучше"}],"correct":1,"explain":{"uz":"Qadoqlash xatolari qo''shimcha xarajat va kechikishga olib keladi.","ru":"Ошибки упаковки ведут к расходам и задержкам."}}]}'::jsonb),
  ('pricing', 0, 18, true, '{"minutes":6,"icon":"calc","title":{"uz":"Narx belgilash","ru":"Как установить цену"},"summary":{"uz":"Raqobat, foyda va boshlang''ich narx.","ru":"Конкуренты, прибыль и стартовая цена."},"slides":[{"kind":"learn","title":{"uz":"Narx uchta narsaga bog''liq","ru":"Цена зависит от трёх вещей"},"body":{"uz":"Narx sizning xarajatingizdan past bo''lmasligi, raqobatchilar oralig''ida bo''lishi va xaridor ko''radigan qiymatga mos kelishi kerak.","ru":"Цена не должна быть ниже ваших затрат, должна вписываться в диапазон конкурентов и соответствовать ценности для покупателя."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Zararsizlik narxidan yuqori","ru":"Выше точки безубыточности"},{"uz":"Raqobatchilar oralig''ida","ru":"В диапазоне конкурентов"},{"uz":"Sifatga mos","ru":"Соответствует качеству"}]}},{"kind":"learn","title":{"uz":"Narx poygasi xavfi","ru":"Опасность ценовой войны"},"body":{"uz":"Faqat eng arzon bo''lishga urinish – xavfli yo''l. Raqobatchi ham narxni tushiradi va ikkalangiz ham foydasiz qolasiz. Yaxshiroq mahsulot va listing bilan raqobat qiling.","ru":"Пытаться быть самым дешёвым опасно. Конкурент тоже снизит цену, и оба останетесь без прибыли. Конкурируйте лучшим товаром и карточкой."}},{"kind":"learn","title":{"uz":"Misol hisob","ru":"Пример расчёта"},"body":{"uz":"Zararsizlik narxi 7,53 $ bo''lsa va raqobatchilar 11–15 $ oralig''ida sotsa, 12,99 $ dan boshlash mantiqli: foyda qoladi va narx bozorga mos.","ru":"Если точка безубыточности 7,53 $, а конкуренты продают за 11–15 $, разумно начать с 12,99 $: прибыль остаётся, цена в рынке."},"visual":{"kind":"formula","caption":{"uz":"Misol","ru":"Пример"},"lines":[{"label":{"uz":"Zararsizlik narxi","ru":"Точка безубыточности"},"value":"$7.53"},{"label":{"uz":"Raqobatchilar","ru":"Конкуренты"},"value":"$11–15"},{"op":"=","label":{"uz":"Boshlang''ich narx","ru":"Стартовая цена"},"value":"$12.99"}]}},{"kind":"quiz","question":{"uz":"Narx qachon albatta noto''g''ri?","ru":"Когда цена точно неправильная?"},"options":[{"uz":"Raqobatchilardan biroz yuqori","ru":"Чуть выше конкурентов"},{"uz":"Zararsizlik narxidan past","ru":"Ниже точки безубыточности"},{"uz":"Raqobatchilar oralig''ida","ru":"В диапазоне конкурентов"}],"correct":1,"explain":{"uz":"Zararsizlik narxidan past sotsangiz, har bir sotuvda pul yo''qotasiz.","ru":"Ниже точки безубыточности вы теряете деньги на каждой продаже."}}]}'::jsonb),
  ('ppc', 0, 19, true, '{"minutes":7,"icon":"chart","title":{"uz":"Amazon reklamasi (PPC) asoslari","ru":"Основы рекламы Amazon (PPC)"},"summary":{"uz":"Sponsored Products, ACoS va byudjet.","ru":"Sponsored Products, ACoS и бюджет."},"slides":[{"kind":"learn","title":{"uz":"PPC nima","ru":"Что такое PPC"},"body":{"uz":"PPC – bosish uchun to''lov. Mahsulotingiz qidiruvda reklama sifatida chiqadi va kimdir bosganda pul to''laysiz. Yangi mahsulot uchun bu birinchi xaridorlarni topishning asosiy yo''li.","ru":"PPC – оплата за клик. Ваш товар показывается в поиске как реклама, и вы платите, когда кто-то нажимает. Для нового товара это главный способ найти первых покупателей."},"visual":{"kind":"flow","steps":[{"uz":"Kalit so''z","ru":"Запрос"},{"uz":"Reklama ko''rinadi","ru":"Показ рекламы"},{"uz":"Bosish (to''lov)","ru":"Клик (оплата)"},{"uz":"Xarid","ru":"Покупка"}]}},{"kind":"learn","title":{"uz":"ACoS","ru":"ACoS"},"body":{"uz":"ACoS – reklamaga sarflangan pulning reklamadan kelgan sotuvga nisbati. Qancha past bo''lsa, reklama shuncha samarali.","ru":"ACoS – отношение расходов на рекламу к продажам с рекламы. Чем ниже, тем эффективнее реклама."},"visual":{"kind":"formula","caption":{"uz":"Misol","ru":"Пример"},"lines":[{"label":{"uz":"Reklama xarajati","ru":"Расход на рекламу"},"value":"$30"},{"op":"÷","label":{"uz":"Reklamadan sotuv","ru":"Продажи с рекламы"},"value":"$120"},{"op":"=","label":{"uz":"ACoS","ru":"ACoS"},"value":"25%"}]}},{"kind":"learn","title":{"uz":"Zararsiz ACoS","ru":"Безубыточный ACoS"},"body":{"uz":"Reklamasiz marjangiz 36% bo''lsa, ACoS 36% dan oshganda har bir reklama sotuvi zarar keltiradi. Boshlanishda biroz zarar bo''lishi mumkin, lekin chegarani bilib turing.","ru":"Если маржа без рекламы 36%, то при ACoS выше 36% каждая продажа с рекламы убыточна. На старте небольшой минус возможен, но знайте свою границу."}},{"kind":"learn","title":{"uz":"Qanday boshlash","ru":"Как начать"},"body":{"uz":"Kichik kunlik byudjet bilan avtomatik kampaniyadan boshlang. 1–2 haftadan keyin qaysi so''zlar sotganini ko''ring va ularni qo''lda boshqariladigan kampaniyaga o''tkazing. Sotmayotgan so''zlarni o''chiring.","ru":"Начните с автоматической кампании и небольшого дневного бюджета. Через 1–2 недели посмотрите, какие запросы продавали, и перенесите их в ручную кампанию. Неработающие запросы отключите."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Avtomatik kampaniya","ru":"Автоматическая кампания"},{"uz":"Kichik kunlik byudjet","ru":"Небольшой дневной бюджет"},{"uz":"Har hafta hisobotni ko''rish","ru":"Каждую неделю смотреть отчёт"},{"uz":"Yaxshi so''zlarni qo''lda boshqarish","ru":"Лучшие запросы – в ручную кампанию"}]}},{"kind":"quiz","question":{"uz":"Reklamaga 20 $ sarflab, reklamadan 80 $ sotdingiz. ACoS qancha?","ru":"Потратили 20 $ на рекламу и продали с неё на 80 $. Какой ACoS?"},"options":[{"uz":"25%","ru":"25%"},{"uz":"40%","ru":"40%"},{"uz":"400%","ru":"400%"}],"correct":0,"explain":{"uz":"20 ÷ 80 = 0,25, ya''ni 25%.","ru":"20 ÷ 80 = 0,25, то есть 25%."}}]}'::jsonb),
  ('reviews-rules', 0, 20, true, '{"minutes":5,"icon":"check","title":{"uz":"Sharhlarni to''g''ri yo''l bilan olish","ru":"Отзывы честным путём"},"summary":{"uz":"Nima mumkin va nima qat''iyan taqiqlangan.","ru":"Что можно и что строго запрещено."},"slides":[{"kind":"learn","title":{"uz":"Taqiqlangan usullar","ru":"Запрещённые способы"},"body":{"uz":"Amazon soxta va pullik sharhlarga qattiq qarshi. Ular uchun listing o''chirilishi va hisob yopilishi mumkin.","ru":"Amazon строго борется с фейковыми и платными отзывами. За них могут удалить карточку и закрыть аккаунт."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Sharh uchun pul yoki sovg''a berish","ru":"Платить или дарить за отзыв"},{"uz":"Faqat ijobiy sharh so''rash","ru":"Просить только положительный отзыв"},{"uz":"Do''st va qarindoshlardan sharh yozdirish","ru":"Отзывы от друзей и родных"},{"uz":"Raqobatchiga yomon sharh yozish","ru":"Плохие отзывы конкурентам"}]}},{"kind":"learn","title":{"uz":"Ruxsat etilgan usullar","ru":"Разрешённые способы"},"body":{"uz":"Xaridordan neytral tarzda fikr so''rash mumkin. Eng yaxshi usul – sifatli mahsulot va halol tavsif.","ru":"Можно нейтрально попросить покупателя оставить отзыв. Лучший способ – качественный товар и честное описание."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Seller Central''dagi \"Request a Review\" tugmasi","ru":"Кнопка «Request a Review» в Seller Central"},{"uz":"Amazon Vine dasturi (brend egalari uchun)","ru":"Программа Amazon Vine (для владельцев бренда)"},{"uz":"Qutidagi neytral eslatma va yo''riqnoma","ru":"Нейтральная вкладка с инструкцией"}]}},{"kind":"learn","title":{"uz":"Yomon sharhga javob","ru":"Ответ на плохой отзыв"},"body":{"uz":"Salbiy sharhdan jahl qilmang. Sababini o''rganing va mahsulotni yaxshilang. Bu keyingi partiyani kuchliroq qiladi.","ru":"Не злитесь на негатив. Разберитесь в причине и улучшите товар. Следующая партия станет сильнее."}},{"kind":"quiz","question":{"uz":"Qaysi biri ruxsat etilgan?","ru":"Что разрешено?"},"options":[{"uz":"Sharh uchun chegirma berish","ru":"Скидка за отзыв"},{"uz":"\"Request a Review\" tugmasidan foydalanish","ru":"Кнопка «Request a Review»"},{"uz":"Do''stlardan 5 yulduz so''rash","ru":"Попросить друзей поставить 5 звёзд"}],"correct":1,"explain":{"uz":"\"Request a Review\" – Amazon''ning o''zi bergan rasmiy usul.","ru":"«Request a Review» – официальный способ от самого Amazon."}}]}'::jsonb),
  ('inventory', 0, 21, true, '{"minutes":7,"icon":"truck","title":{"uz":"Zaxirani rejalashtirish","ru":"Планирование запасов"},"summary":{"uz":"Qachon va qancha qayta buyurtma qilish.","ru":"Когда и сколько дозаказывать."},"slides":[{"kind":"learn","title":{"uz":"Ikki xavf","ru":"Две опасности"},"body":{"uz":"Tovar tugab qolsa, sotuvlar to''xtaydi va qidiruvdagi o''rningiz pasayadi. Juda ko''p bo''lsa, pul omborda qotib qoladi va saqlash uchun ko''proq to''laysiz.","ru":"Если товар закончится, продажи остановятся и позиции в поиске упадут. Если его слишком много, деньги застрянут на складе, и хранение обойдётся дороже."},"visual":{"kind":"compare","left":{"title":{"uz":"Kam zaxira","ru":"Мало запаса"},"items":[{"uz":"Sotuv to''xtaydi","ru":"Продажи стоят"},{"uz":"Reyting tushadi","ru":"Падают позиции"}]},"right":{"title":{"uz":"Ortiqcha zaxira","ru":"Лишний запас"},"items":[{"uz":"Pul qotadi","ru":"Деньги заморожены"},{"uz":"Saqlash qimmat","ru":"Дорогое хранение"}]}}},{"kind":"learn","title":{"uz":"Qayta buyurtma nuqtasi","ru":"Точка дозаказа"},"body":{"uz":"Qayta buyurtmani tovar tugashidan oldin, ishlab chiqarish va yetkazish vaqtini hisobga olib berasiz.","ru":"Дозаказывайте до того, как товар закончится, с учётом времени производства и доставки."},"visual":{"kind":"formula","caption":{"uz":"Misol","ru":"Пример"},"lines":[{"label":{"uz":"Kunlik sotuv","ru":"Продажи в день"},"value":"5"},{"op":"×","label":{"uz":"Ishlab chiqarish + yetkazish, kun","ru":"Производство + доставка, дней"},"value":"45"},{"op":"+","label":{"uz":"Xavfsizlik zaxirasi","ru":"Страховой запас"},"value":"50"},{"op":"=","label":{"uz":"Qayta buyurtma nuqtasi, dona","ru":"Точка дозаказа, шт."},"value":"275"}]}},{"kind":"learn","title":{"uz":"Amalda","ru":"На практике"},"body":{"uz":"Omborda 275 dona qolganda yangi partiyani buyurtma qiling. Sotuv tezligi o''zgarsa, hisobni yangilang. Birinchi partiyani kichik qiling: talabni ko''rmaguncha katta buyurtma bermang.","ru":"Когда на складе останется 275 штук, заказывайте новую партию. Если скорость продаж меняется, пересчитайте. Первую партию делайте небольшой: не заказывайте много, пока не увидите спрос."}},{"kind":"quiz","question":{"uz":"Kuniga 4 dona sotiladi, yetkazish va ishlab chiqarish 30 kun, xavfsizlik zaxirasi 40. Qayta buyurtma nuqtasi?","ru":"Продажи 4 в день, производство и доставка 30 дней, страховой запас 40. Точка дозаказа?"},"options":[{"uz":"120","ru":"120"},{"uz":"160","ru":"160"},{"uz":"74","ru":"74"}],"correct":1,"explain":{"uz":"4 × 30 + 40 = 160 dona.","ru":"4 × 30 + 40 = 160 штук."}}]}'::jsonb),
  ('getting-paid', 0, 22, true, '{"minutes":6,"icon":"shield","title":{"uz":"Pul olish va hisob-kitob","ru":"Выплаты и учёт"},"summary":{"uz":"Amazon qanday to''laydi va nimani yozib borish kerak.","ru":"Как платит Amazon и что записывать."},"slides":[{"kind":"learn","title":{"uz":"Amazon qanday to''laydi","ru":"Как платит Amazon"},"body":{"uz":"Amazon sotuvdan tushgan pulni to''lovlar va komissiyalarni ayirib, muntazam ravishda sotuvchi bank hisobiga o''tkazadi. To''lov jadvali va qo''llab-quvvatlanadigan davlatlarni Seller Central''da tekshiring.","ru":"Amazon регулярно переводит деньги с продаж на банковский счёт продавца, вычтя сборы и комиссии. График выплат и поддерживаемые страны смотрите в Seller Central."},"visual":{"kind":"flow","steps":[{"uz":"Sotuv","ru":"Продажа"},{"uz":"Komissiyalar ayiriladi","ru":"Вычет сборов"},{"uz":"Muntazam to''lov","ru":"Регулярная выплата"},{"uz":"Bank hisobi","ru":"Банковский счёт"}]}},{"kind":"learn","title":{"uz":"O''zbekistondan pul olish","ru":"Получение денег в Узбекистане"},"body":{"uz":"To''lov hisobi ota-ona yoki vasiy nomida bo''ladi. Ba''zi sotuvchilar xalqaro to''lov xizmatlaridan foydalanadi. Qaysi usul ishlashini va komissiyalarini rasmiy manbalardan tekshiring, qarorni ota-onangiz bilan qabul qiling.","ru":"Счёт для выплат оформляется на родителя или опекуна. Некоторые продавцы используют международные платёжные сервисы. Какой способ работает и какие у него комиссии – проверяйте в официальных источниках и решайте вместе с родителями."}},{"kind":"learn","title":{"uz":"Har bir so''mni yozib boring","ru":"Записывайте каждую сумму"},"body":{"uz":"Haqiqiy foydani bilish va soliqni to''g''ri hisoblash uchun barcha kirim va chiqimlarni saqlang. Soliq masalalarida mutaxassis bilan maslahatlashing.","ru":"Чтобы знать реальную прибыль и правильно считать налоги, сохраняйте все доходы и расходы. По налогам консультируйтесь со специалистом."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Zavod hisob-fakturalari","ru":"Счета фабрики"},{"uz":"Yetkazish va bojxona hujjatlari","ru":"Документы доставки и таможни"},{"uz":"Amazon to''lov hisobotlari","ru":"Отчёты о выплатах Amazon"},{"uz":"Reklama xarajatlari","ru":"Расходы на рекламу"}]}},{"kind":"learn","title":{"uz":"Idrok''da daraja","ru":"Уровень в Idrok"},"body":{"uz":"Keyingi darajaga o''tish uchun haqiqiy, hisobga tushgan sof foyda kerak. Administrator uni hujjatlar asosida tekshiradi, shuning uchun hisobotlarni saqlang.","ru":"Для перехода на следующий уровень нужна реальная чистая прибыль, полученная на счёт. Администратор проверяет её по документам, поэтому храните отчёты."}},{"kind":"quiz","question":{"uz":"Haqiqiy sof foydani bilish uchun nima kerak?","ru":"Что нужно, чтобы знать реальную чистую прибыль?"},"options":[{"uz":"Faqat sotuv summasi","ru":"Только сумма продаж"},{"uz":"Barcha kirim va chiqimlar yozuvi","ru":"Учёт всех доходов и расходов"},{"uz":"Sharhlar soni","ru":"Число отзывов"}],"correct":1,"explain":{"uz":"Sof foyda = barcha kirim minus barcha chiqim.","ru":"Чистая прибыль = все доходы минус все расходы."}}]}'::jsonb),
  ('uzum-market', 0, 23, true, '{"minutes":6,"icon":"globe","title":{"uz":"Uzum Market''da sotish","ru":"Продажи на Uzum Market"},"summary":{"uz":"Mahalliy bozorning o''ziga xos tomonlari.","ru":"Особенности местного рынка."},"slides":[{"kind":"learn","title":{"uz":"Nega Uzum","ru":"Почему Uzum"},"body":{"uz":"Uzum Market – O''zbekistondagi yirik onlayn bozor. Xaridorlar yaqin, til va to''lov tanish, yetkazish tez. Bu tajriba orttirish uchun yaxshi joy.","ru":"Uzum Market – крупный онлайн-рынок Узбекистана. Покупатели рядом, язык и оплата привычные, доставка быстрая. Хорошее место, чтобы набраться опыта."}},{"kind":"learn","title":{"uz":"Ish tartibi","ru":"Как это устроено"},"body":{"uz":"Odatda sotuvchi tovarni Uzum omboriga topshiradi, Uzum esa saqlaydi va xaridorga yetkazadi. Aniq modellar, talablar va muddatlarni sotuvchilar kabinetida tekshiring.","ru":"Обычно продавец сдаёт товар на склад Uzum, а Uzum хранит и доставляет покупателю. Точные модели, требования и сроки смотрите в кабинете продавца."},"visual":{"kind":"flow","steps":[{"uz":"Sotuvchi","ru":"Продавец"},{"uz":"Uzum ombori","ru":"Склад Uzum"},{"uz":"Topshirish punkti","ru":"Пункт выдачи"},{"uz":"Xaridor","ru":"Покупатель"}]}},{"kind":"learn","title":{"uz":"Kartochka sifati","ru":"Качество карточки"},"body":{"uz":"Uzum''da xaridorlar o''zbek va rus tillarida qidiradi. Nomni ikkala tilda tushunarli yozing, aniq rasmlar va o''lchamlarni bering, narxni so''mda to''g''ri hisoblang.","ru":"На Uzum ищут на узбекском и русском. Пишите понятное название на обоих языках, давайте чёткие фото и размеры, считайте цену в сумах правильно."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"O''zbek va rus tilida nom","ru":"Название на узбекском и русском"},{"uz":"Aniq rasmlar","ru":"Чёткие фото"},{"uz":"To''liq xususiyatlar","ru":"Полные характеристики"},{"uz":"So''mda to''g''ri narx","ru":"Правильная цена в сумах"}]}},{"kind":"learn","title":{"uz":"Xarajatlar","ru":"Расходы"},"body":{"uz":"Komissiya toifaga qarab farq qiladi, logistika va saqlash uchun alohida to''lovlar bo''lishi mumkin. Barchasini Idrok kalkulyatoriga kiriting.","ru":"Комиссия зависит от категории, может быть отдельная плата за логистику и хранение. Вносите всё в калькулятор Idrok."}},{"kind":"quiz","question":{"uz":"Uzum''da kartochka nomini qaysi tillarda yozgan ma''qul?","ru":"На каких языках лучше писать название на Uzum?"},"options":[{"uz":"Faqat ingliz tilida","ru":"Только на английском"},{"uz":"O''zbek va rus tillarida","ru":"На узбекском и русском"},{"uz":"Faqat raqamlar bilan","ru":"Только цифрами"}],"correct":1,"explain":{"uz":"Xaridorlar ikkala tilda ham qidiradi.","ru":"Покупатели ищут на обоих языках."}}]}'::jsonb),
  ('account-health', 0, 24, true, '{"minutes":5,"icon":"shield","title":{"uz":"Hisob salomatligi","ru":"Здоровье аккаунта"},"summary":{"uz":"Hisobni yopilishdan qanday saqlash.","ru":"Как не потерять аккаунт."},"slides":[{"kind":"learn","title":{"uz":"Amazon nimani kuzatadi","ru":"Что отслеживает Amazon"},"body":{"uz":"Amazon har bir sotuvchining ishini ko''rsatkichlar orqali kuzatadi. Ular yomonlashsa, hisob to''xtatilishi mumkin. Seller Central''dagi \"Account Health\" sahifasini muntazam tekshiring.","ru":"Amazon следит за работой продавца по показателям. Если они ухудшатся, аккаунт могут приостановить. Регулярно проверяйте страницу «Account Health» в Seller Central."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Buyurtma nuqsonlari darajasi (ODR) – 1% dan past","ru":"Доля проблемных заказов (ODR) – ниже 1%"},{"uz":"Qoidabuzarliklar yo''q","ru":"Нет нарушений правил"},{"uz":"Xaridorga 24 soat ichida javob","ru":"Ответ покупателю в течение 24 часов"}]}},{"kind":"learn","title":{"uz":"Nima xavfli","ru":"Что опасно"},"body":{"uz":"Ko''pchilik hisoblar shu sabablar tufayli muammoga uchraydi.","ru":"Чаще всего аккаунты страдают из-за этого."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Soxta sharhlar","ru":"Фейковые отзывы"},{"uz":"Birovning brendi yoki patentini buzish","ru":"Нарушение чужого бренда или патента"},{"uz":"Yolg''on tavsif","ru":"Ложное описание"},{"uz":"Bir kishiga bir nechta hisob","ru":"Несколько аккаунтов на одного человека"}]}},{"kind":"learn","title":{"uz":"Ogohlantirish kelsa","ru":"Если пришло предупреждение"},"body":{"uz":"Vahimaga tushmang. Xatni diqqat bilan o''qing, sababini tushuning, ota-onangiz bilan maslahatlashing va muddatida aniq javob bering.","ru":"Не паникуйте. Внимательно прочитайте письмо, поймите причину, посоветуйтесь с родителями и ответьте чётко и в срок."}},{"kind":"quiz","question":{"uz":"Qaysi biri hisob uchun xavfli?","ru":"Что опасно для аккаунта?"},"options":[{"uz":"Xaridorga tez javob berish","ru":"Быстро отвечать покупателю"},{"uz":"Bir kishiga bir nechta hisob ochish","ru":"Открыть несколько аккаунтов на одного человека"},{"uz":"Halol tavsif yozish","ru":"Писать честное описание"}],"correct":1,"explain":{"uz":"Amazon odatda bir sotuvchiga bitta hisobga ruxsat beradi.","ru":"Amazon обычно разрешает одному продавцу один аккаунт."}}]}'::jsonb),
  ('launch-plan', 0, 25, true, '{"minutes":8,"icon":"play","title":{"uz":"Birinchi ishga tushirish rejasi","ru":"План первого запуска"},"summary":{"uz":"G''oyadan birinchi sotuvgacha – barcha qadamlar.","ru":"Все шаги от идеи до первой продажи."},"slides":[{"kind":"learn","title":{"uz":"Butun yo''l","ru":"Весь путь"},"body":{"uz":"Barcha darslar bitta reja bo''lib birlashadi. Har bir qadamni tugatmasdan keyingisiga o''tmang.","ru":"Все уроки складываются в один план. Не переходите к следующему шагу, не закончив предыдущий."},"visual":{"kind":"flow","steps":[{"uz":"Tadqiqot","ru":"Исследование"},{"uz":"Yetkazib beruvchi","ru":"Поставщик"},{"uz":"Namuna","ru":"Образец"},{"uz":"Buyurtma","ru":"Заказ"},{"uz":"Sotuv","ru":"Продажа"}]}},{"kind":"learn","title":{"uz":"1-bosqich: tadqiqot","ru":"Этап 1: исследование"},"body":{"uz":"0-daraja qoidalariga mos mahsulot tanlang, talab va raqobatni tekshiring, kalit so''zlarni yig''ing va foydani hisoblang.","ru":"Выберите товар по правилам уровня 0, проверьте спрос и конкурентов, соберите ключевые слова и посчитайте прибыль."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Qoidalarga mos","ru":"Подходит под правила"},{"uz":"Talab bor","ru":"Есть спрос"},{"uz":"Yaxshilash imkoni bor","ru":"Есть что улучшить"},{"uz":"Foyda ijobiy","ru":"Прибыль положительная"}]}},{"kind":"learn","title":{"uz":"2-bosqich: yetkazib beruvchi va namuna","ru":"Этап 2: поставщик и образец"},"body":{"uz":"3–5 ta taklif oling, solishtiring, namunani tekshiring. Har bir xaridni siz va ota-onangiz birga tasdiqlaysiz.","ru":"Получите 3–5 предложений, сравните, проверьте образец. Каждую покупку вы одобряете вместе с родителями."}},{"kind":"learn","title":{"uz":"3-bosqich: tayyorlash va jo''natish","ru":"Этап 3: подготовка и отправка"},"body":{"uz":"Brend, shtrix-kodlar, qadoqlash va yorliqlarni tayyorlang. Listingni yarating, jo''natma tuzing va ekspeditorga topshiring.","ru":"Подготовьте бренд, штрихкоды, упаковку и этикетки. Создайте карточку и поставку, передайте груз экспедитору."}},{"kind":"learn","title":{"uz":"4-bosqich: ishga tushirish va o''rganish","ru":"Этап 4: запуск и анализ"},"body":{"uz":"Narxni belgilang, kichik reklama bilan boshlang, sharhlarni to''g''ri yo''l bilan so''rang, zaxirani kuzating. Har hafta raqamlarni ko''rib, xulosa qiling.","ru":"Установите цену, начните с небольшой рекламы, честно просите отзывы, следите за запасом. Каждую неделю смотрите цифры и делайте выводы."},"visual":{"kind":"big","icon":"flame","text":{"uz":"Kichik boshlang, tez o''rganing, halol ishlang","ru":"Начните с малого, учитесь быстро, работайте честно"}}},{"kind":"quiz","question":{"uz":"Katta buyurtmadan oldin qaysi qadam albatta bo''lishi kerak?","ru":"Какой шаг обязателен перед большим заказом?"},"options":[{"uz":"Reklama byudjetini oshirish","ru":"Увеличить рекламный бюджет"},{"uz":"Namunani tekshirish va tasdiqlash","ru":"Проверить и одобрить образец"},{"uz":"Narxni eng past qilish","ru":"Поставить самую низкую цену"}],"correct":1,"explain":{"uz":"Namuna va tasdiqlash – pul sarflashdan oldingi asosiy himoya.","ru":"Образец и одобрение – главная защита перед тратой денег."}}]}'::jsonb)
